import{_ as t,o as r,c as a,a5 as d}from"./chunks/framework.DJo0M80U.js";const M=JSON.parse('{"title":"用 reactive(new Map()) 和用 ref(new Map())","description":"在 Vue 3 的响应式系统里，用 reactive(new Map()) 和用 ref(new Map()) 看似都能“包裹”一个 Map，但二者在拦截、依赖收集、触发更新等方面有本质区别： 一、底层原理对比 特性 reactive(new Map()) ref(new Map。","frontmatter":{"title":"用 reactive(new Map()) 和用 ref(new Map())","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","响应式与组合式 API"],"description":"在 Vue 3 的响应式系统里，用 reactive(new Map()) 和用 ref(new Map()) 看似都能“包裹”一个 Map，但二者在拦截、依赖收集、触发更新等方面有本质区别： 一、底层原理对比 特性 reactive(new Map()) ref(new Map。","sidebarWeight":155,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/响应式问题/用 reactive(new Map()) 和用 ref(new Map()).md"},"headers":[],"relativePath":"posts/Vue系统教程/03-响应式与组合式 API/用 reactive(new Map()) 和用 ref(new Map()).md","filePath":"posts/Vue系统教程/03-响应式与组合式 API/用 reactive(new Map()) 和用 ref(new Map()).md"}'),n={name:"posts/Vue系统教程/03-响应式与组合式 API/用 reactive(new Map()) 和用 ref(new Map()).md"};function s(o,e,p,l,i,c){return r(),a("div",null,[...e[0]||(e[0]=[d('<div><h1 id="用-reactive-new-map-和用-ref-new-map" tabindex="-1">用 reactive(new Map()) 和用 ref(new Map()) <a class="header-anchor" href="#用-reactive-new-map-和用-ref-new-map" aria-label="Permalink to &quot;用 reactive(new Map()) 和用 ref(new Map())&quot;">​</a></h1><blockquote><p>本节目标：理解“用 reactive(new Map()) 和用 ref(new Map())”的核心思路，并能把它用于实际开发或面试表达。 在 Vue 3 的响应式系统里，用 reactive(new Map()) 和用 ref(new Map()) 看似都能“包裹”一个 Map，但二者在拦截、依赖收集、触发更新等方面有本质区别：</p></blockquote><p><strong>一、底层原理对比</strong></p><table tabindex="0"><thead><tr><th></th><th></th><th></th></tr></thead><tbody><tr><td><strong>特性</strong></td><td><strong>reactive(new Map())</strong></td><td><strong>ref(new Map())</strong></td></tr><tr><td>包装方式</td><td>深度代理，将传入对象「递归」变成 Proxy</td><td>将整个值（包括对象）封装到 .value，但内部对象不是递归代理</td></tr><tr><td>拦截方式</td><td>通过 Proxy 针对对象所有操作（属性读/写、方法调用、迭代）做劫持</td><td></td></tr><tr><td>并对 Map 的 .get/.set/.delete/forEach/keys/values/entries 等做了专门的响应式处理（“集合类型”专门 instrumentations）</td><td>只对 .value 的读写做拦截</td><td></td></tr><tr><td>对 .value 本身赋新引用时触发依赖更新</td><td></td><td></td></tr><tr><td><strong>不</strong>会自动拦截 .value（即 Map 本身）的内部修改</td><td></td><td></td></tr><tr><td>依赖收集</td><td>任何对 Map 方法的调用（get/set/delete/has、迭代、访问 size）都会被 track 住，只要后续某条 map.set(...) 或者 .delete(...)，对应的依赖就会触发更新</td><td>只有当你做 ref.value = 新 Map 时，依赖才会触发</td></tr><tr><td>对 ref.value.set(...)、delete 等内部修改<strong>不会</strong>触发响应</td><td></td><td></td></tr><tr><td>更新触发</td><td>map.set(key, val)、map.delete(key)、map.clear() 等都会触发相应的 effect 重跑</td><td>必须显式替换引用：ref.value = newMap 才会触发</td></tr><tr><td>对 ref.value 内部的操作无感知</td><td></td><td></td></tr><tr><td>适用场景</td><td>需要「对 Map 内部读写都响应」的场景，比如增量更新</td><td></td></tr><tr><td>可以直接 reactive(new Map())，用 .set() / .delete() 更新即可自动刷新视图</td><td>仅在「整块替换」Map 时用得上，比如你一次性拿到新 Map 要直接换过去</td><td></td></tr><tr><td>不适合频繁的增删改场景</td><td></td><td></td></tr></tbody></table><p><strong>二、示例对比</strong><strong>1. reactive(new Map())</strong> import { reactive, computed } from &#39;vue&#39; const store = { orders: reactive(new Map&lt;number, Order&gt;())} // 组件里const allOrders = computed(() =&gt; Array.from(store.orders.values())) // 往里加一条 → 视图马上更新store.orders.set(123, { /* ... */ }) // 删除一条 → 也会更新store.orders.delete(123)</p><ul><li>因为 orders 是 Proxy，当你调用 .set()、.delete() 后，Vue 会检测到“集合类型”的变更，自动触发依赖 allOrders 的 computed/模板重算。</li></ul><p><strong>2. ref(new Map())</strong> import { ref, computed } from &#39;vue&#39; const store = { orders: ref(new Map&lt;number, Order&gt;())} // 组件里const allOrders = computed(() =&gt; Array.from(store.orders.value.values())) // 这样做<strong>不会</strong>更新视图：store.orders.value.set(123, { /* ... <em>/ }) // 必须整体替换才会：store.orders.value = new Map([[123, {/</em>...*/}]])</p><ul><li>.value.set(...) 并不会触发任何依赖，因为 Vue 只监控对 .value 属性的赋值操作。</li></ul><p><strong>三、性能与选择</strong></p><ul><li>如果你的业务是「<strong>频繁增删改</strong>」一个 Map（比如订单不断进来、取消），用 reactive(new Map()) 最方便：只要 .set()/.delete()，就会响应式更新，性能好、代码简洁。</li><li>如果你仅仅是在某个时刻「<strong>一次性拿到全量 Map</strong>」然后替换，且之后不再做内部频繁修改，用 ref(new Map()) 然后 $patch 或直接 .value = newMap 会更简洁，也不会多拦截多消耗。</li></ul><p>一般金融交易这种「增量事件驱动」场景，<strong>推荐</strong>用 reactive(new Map())，保证每一次事件（下单、改单、撤单）都能被 Vue 真正拦截并触发更新。</p></div>',1)])])}const v=t(n,[["render",s]]);export{M as __pageData,v as default};
